// APEX RunVex. Inputs: vector a, b; float t. Output: vector result.
// No '@' syntax in APEX VEX -- operate on the named ports directly.
result = lerp(a, b, t);

// APEX RunVex. Inputs: vector t; float s. Output: matrix xform.
matrix m = ident();
scale(m, set(s, s, s));
translate(m, t);
xform = m;

// APEX RunVex. Inputs: float value, inmin, inmax, outmin, outmax.
// Output: float out.
out = fit(value, inmin, inmax, outmin, outmax);

// Point Wrangle on points that instance lights in Solaris.
// These attributes ride along as per-light overrides.
@intensity = fit01(rand(@ptnum), chf("imin"), chf("imax"));
@Cd = lerp(chv("warm"), chv("cool"), rand(@ptnum + 2.3));

// Point Wrangle: a spot light points down its local -Z, so rotate
// -Z onto the surface normal.
p@orient = dihedral({0, 0, -1}, normalize(@N));

// Point Wrangle: dim lights farther from a focus point with an
// exponential falloff.
float d = distance(@P, chv("focus"));
@intensity = chf("base") * exp(-d * chf("falloff"));

// Snippet VOP in a material network. I is the incident ray, so
// -I points toward the camera. Add a rim that grows at grazing
// angles.
vector nN = normalize(N);
vector v  = normalize(-I);
float f = pow(1.0 - clamp(dot(nN, v), 0, 1), chf("rim_power"));
Cf += f * chv("rim_color");

// Snippet VOP: tint the surface using world-space noise so the
// variation stays put as geometry deforms.
float n = noise(P * chf("scale"));
Cf = lerp(chv("color_a"), chv("color_b"), n);

// Snippet VOP: vertical colour gradient between two bounds.
float h = fit(P.y, chf("low"), chf("high"), 0, 1);
Cf = lerp(chv("bottom"), chv("top"), clamp(h, 0, 1));

// Displacement Snippet VOP: signed noise offset along the normal.
// Refit shading normals afterward (Compute Normal VOP / Displace
// node option) so lighting follows the new surface.
float d = (noise(P * chf("freq")) - 0.5) * 2.0 * chf("amp");
P += normalize(N) * d;

// Standalone CVEX surface shader. Compile with vcc:
//   vcc simple_surface.vfl
cvex simple_surface(
        export vector Cf = {0, 0, 0};
        vector P = {0, 0, 0};
        vector N = {0, 1, 0};
        vector baseColor = {0.6, 0.6, 0.6})
{
    vector nN  = normalize(N);
    vector L   = normalize({0.4, 1.0, 0.3});
    float  ndl = max(dot(nN, L), 0);
    Cf = baseColor * (0.2 + 0.8 * ndl);
}

// Snippet VOP: a checkerboard from the surface UVs (s, t).
int cx = (int)floor(s * chf("tiles"));
int cy = (int)floor(t * chf("tiles"));
float c = (cx + cy) % 2;
Cf = lerp(chv("color_a"), chv("color_b"), c);

// Point Wrangle on the MPM source geometry (before the MPM
// Solver SOP). v@v becomes the particles' initial velocity.
v@v = chv("launch_velocity");   // e.g. {3, 2, 0}

// Point Wrangle after the MPM Solver: map speed to a ramp.
float spd = length(v@v);
@Cd = chramp("speed_ramp", fit(spd, 0, chf("max_speed"), 0, 1));

// Point Wrangle after the MPM Solver. @Je is the elastic volume
// ratio: <1 compressed, >1 stretched. Map distance from 1.
float strain = abs(f@Je - 1.0);
@Cd = chramp("strain_ramp", fit(strain, 0, chf("max_strain"), 0, 1));

// Geometry Wrangle inside a solver stepping the MPM points.
// Outward impulse, scaled by the substep time for stability.
vector center = chv("center");
vector dir = @P - center;
float d = max(length(dir), 1e-4);
v@v += (dir / d) * chf("strength") * f@TimeInc;

// Geometry Wrangle inside a solver: tangential swirl around an
// axis through 'center'.
vector axis   = normalize(chv("axis"));
vector center = chv("center");
vector r = @P - center;
vector tangent = cross(axis, r);
v@v += normalize(tangent) * chf("strength") * f@TimeInc;

// Geometry Wrangle inside a solver: divergence-free turbulence.
vector p = @P * chf("freq") + f@Time * chv("evolve");
v@v += curlnoise(p) * chf("amp") * f@TimeInc;

// Geometry Wrangle inside a solver: zero the velocity of any
// particle below the floor to pin it.
if (@P.y < chf("floor"))
    v@v = {0, 0, 0};

// Point Wrangle on the MPM source: map an input f@density into a
// particle radius range.
@pscale = fit(f@density, chf("dmin"), chf("dmax"),
              chf("rmin"), chf("rmax"));

// Point Wrangle: build an orient quaternion that rotates a
// reference up-vector onto each point's surface normal. Copy to
// Points reads p@orient automatically.
vector up = chv("up");            // e.g. {0, 1, 0}
vector n  = normalize(@N);
p@orient  = dihedral(up, n);

// Point Wrangle: smaller pscale where neighbours are dense.
int h = pcopen(0, "P", @P, chf("radius"), chi("maxpts"));
int n = pcnumfound(h);
@pscale = fit(n, 1, chi("maxpts"), chf("maxsize"), chf("minsize"));
pcclose(h);

// Point/Prim Wrangle downstream of a Connectivity SOP that
// writes i@class. Each piece gets a stable random colour.
@Cd = rand(i@class * 0.731 + 12.3);

// Detail Wrangle: connect every input point, in order, into one
// open polyline.
int n    = npoints(0);
int prim = addprim(0, "polyline");
for (int i = 0; i < n; i++)
    addvertex(0, prim, i);

// Point Wrangle: accumulate octaves of absolute noise (ridged
// fBm) and push each point along its normal.
float amp  = chf("amp");
float freq = chf("freq");
float n = 0;
for (int o = 0; o < 4; o++) {
    float g = pow(2.0, o);
    n += abs(noise(@P * freq * g)) / g;
}
@P += normalize(@N) * n * amp;

// Point Wrangle: remove any point outside a spherical radius.
if (length(@P) > chf("radius"))
    removepoint(0, @ptnum);

// Point Wrangle (after a Normal SOP): higher @curve where the
// surface bends away from its neighbours.
int nb[] = neighbours(0, @ptnum);
vector navg = {0, 0, 0};
foreach (int pt; nb)
    navg += point(0, "N", pt);
navg = normalize(navg / max(len(nb), 1));
f@curve = 1.0 - dot(navg, normalize(@N));

// Primitive Wrangle: write point attribute curveu in [0,1] by
// accumulated arc length along each polyline.
int pts[] = primpoints(0, @primnum);
float total = 0;
for (int i = 1; i < len(pts); i++)
    total += distance(point(0, "P", pts[i-1]), point(0, "P", pts[i]));
float run = 0;
setpointattrib(0, "curveu", pts[0], 0.0);
for (int i = 1; i < len(pts); i++) {
    run += distance(point(0, "P", pts[i-1]), point(0, "P", pts[i]));
    setpointattrib(0, "curveu", pts[i], total > 0 ? run / total : 0.0);
}

// Point Wrangle: independent random orient, size and colour per
// copy. Offsetting the seed decorrelates each attribute.
float seed = @ptnum;
p@orient = quaternion(rand(seed) * 2 * PI, {0, 1, 0});
@pscale  = fit01(rand(seed + 1.7), chf("smin"), chf("smax"));
@Cd      = set(rand(seed + 3.1), rand(seed + 5.2), rand(seed + 7.3));

// Point Wrangle: snap each position to the nearest grid cell so a
// following Fuse SOP welds coincident points cleanly.
float g = chf("grid");
@P = round(@P / g) * g;

// Point Wrangle feeding a Solaris Instancer (via SOP Import).
// USD point instancing reads orient (vector4), pscale and an
// integer index used to pick a prototype.
p@orient  = quaternion(rand(@ptnum) * 2 * PI, {0, 1, 0});
@pscale   = fit01(rand(@ptnum + 4.6), 0.8, 1.2);
i@variant = int(rand(@ptnum + 9.1) * chi("num_variants"));

// Point Wrangle before SOP Import. Cd is carried into USD as
// primvars:displayColor, so this tints the imported prim.
@Cd = chramp("tint", fit(@P.y, chf("low"), chf("high"), 0, 1));

// Primitive Wrangle: build a deterministic USD prim path per
// piece so references stay stable across cooks.
s@name = sprintf("/geo/piece_%d", i@piece);

// Primitive Wrangle: assign USD purpose so the prim shows as a
// lightweight proxy in the viewport but the full mesh at render.
s@usdpurpose = (i@is_proxy) ? "proxy" : "render";

// Point Wrangle in a SOP that a TOP graph cooks per work item.
// A Wedge TOP exposes its value as a detail attribute 'seed'; use
// it so every work item produces a different variant.
float seed = detail(0, "seed", 0);
@P += vector(rand(set(@ptnum, seed))) * chf("jitter");

// Detail Wrangle in a PDG-cooked SOP. The TOP graph passes the
// work item index in as the detail attribute 'pdg_index'; copy it
// onto a stable attribute for a later merge to sort on.
i@workitem = int(detail(0, "pdg_index", 0));
